 [2520]="Priestess A'moora wants you to place Lady Sathrah's silvery spinnerets at the fountain inside the temple, and then return to her.",
 [2521]="In your journeys throughout the Blasted Lands, should you ever come across a Flawless Draenethyst Sphere, take the item back to Kum'isha the Collector.\nBe warned, this gem is one of the most rare crystals in all of Azeroth. Any creature in these lands could be holding a Flawless Draenethyst Sphere.\nYou will be rewarded for each Flawless Draenethyst Sphere you have collected.",
 [2522]="Find and return a Flawless Draenethyst Sphere to Kum'isha the Collector.",
