 [4022]="Show Cyrus Therepentous the Black Dragonflight Molt you received from Kalaran Windblade.",
 [4023]="Show Cyrus Therepentous proof of your worth.\nYou have a feeling that Cyrus already knows that you are unworthy.",
 [4024]="Travel to Blackrock Depths and slay Bael'Gar.\nYou only know that the giant resides inside Blackrock Depths. Remember to use the Altered Black Dragonflight Molt on Bael'Gar's remains to capture the Fiery Essence.\nReturn the Encased Fiery Essence to Cyrus Therepentous.",
 [4061]="Venture to the Burning Steppes and recover 10 Fractured Elemental Shards for Hierophant Theodora Mulvadania.\nYou recall Theodora mentioning the golems and elementals of that region as being a source for these shards.",
 [4062]="Take the Elemental Shard Sample to Lotwil Veriatus.\nYou recall Theodora saying that Lotwil was stationed in a camp to the east.",
 [4063]="Find and slay Golem Lord Argelmach. Return his head to Lotwil. You will also need to collect 10 Intact Elemental Cores from the Ragereaver Golems and Warbringer Constructs protecting Argelmach. You know this because you are psychic.",
 [4081]="Venture to Blackrock Depths and destroy the vile aggressors!\nWarlord Goretooth wants you to kill 15 Anvilrage Guardsmen, 10 Anvilrage Wardens and 5 Anvilrage Footmen. Return to him once your task is complete.",
 [4082]="Venture to Blackrock Depths and destroy the vile aggressors!\nWarlord Goretooth wants you to kill 10 Anvilrage Medics, 10 Anvilrage Soldiers and 10 Anvilrage Officers. Return to him once your task is complete.",
