 [4737]="Speak to Menara Voidrender in the Barrens.",
 [4738]="Speak with Menara Voidrender in the Barrens.",
 [4739]="Speak to Menara Voidrender in the Barrens.",
 [4740]="Find and slay the murloc known as Murkdeep. The creature is thought to be defending the murloc huts south of Auberdine along the water.\nReport the death of Murkdeep to Sentinel Glynda Nal'Shea in Auberdine.",
 [4741]="Trull Failbane in Felwood wants you to hunt 13 Moontouched Owlbeasts.",
 [4742]="Find the three gemstones of command: The Gemstone of Smolderthorn, Gemstone of Spirestone, and Gemstone of Bloodaxe. Return them, along with the Unadorned Seal of Ascension, to Vaelan.\nThe Generals, as told to you by Vaelan, are: War Master Voone of the Smolderthorn; Highlord Omokk of the Spirestone; and Overlord Wyrmthalak of the Bloodaxe.",
 [4743]="Travel to the Wyrmbog in Dustwallow Marsh. Find the ancient drake, Emberstrife and beat him without mercy until his will is broken.\nIt is at that moment which you must place the Unforged Seal of Ascension before the great beast. You must then be quick to use the Orb of Draconic Energy on his weakened form and claim dominion over his mental faculties. Control the beast and force the Flames of the Black Dragonflight upon the Unforged Seal of Ascension!",
 [4761]="Speak with Thundris Windweaver in Auberdine.",
 [4762]="Travel north of Auberdine to the first waterfall along the Cliffspring River and draw a sample from the pool there.\nReturn to Thundris Windweaver in Auberdine with the Cliffspring River Sample.",
 [4763]="Fill the Empty Cleansing Bowl at the Auberdine Moonwell.\nGather a sample of fruit, nut, and grain from the northern Blackwood furbolg camps.\nMix the bowl and place it near the bonfire closest to the Cliffspring River at the northern camp, thus summoning the satyr corruptor.\nTake the Talisman of Corruption and bring it to Thundris Windweaver in Auberdine.",
 [4764]="Bring Doomrigger's Clasp to Mayara Brightwing in the Burning Steppes.",
 [4765]="Bring Ridgewell's Crate to Remington Ridgewell in Stormwind.",
 [4766]="Speak with Mayara Brightwing in the Burning Steppes.",
 [4767]="Bring 10 Highperch Wyvern Eggs to Elu in Freewind Post.",
 [4768]="Bring the Darkstone Tablet to Shadow Mage Vivian Lagrave in Kargath.",
 [4769]="Speak with Shadowmage Vivian Lagrave.",
 [4770]="Escort Pao'ka Swiftmountain from Highperch, and then talk to Motega Firemane in Whitereach Post.",
