 [8730]="Slay Nefarian and recover the Red Scepter Shard. Return the Red Scepter Shard to Anachronos at the Caverns of Time in Tanaris. You have 5 hours to complete this task.",
 [8731]="Report to Krug Skullsplit at the Orgrimmar Legion post in front of Hive'Regal. Prepare your Unsigned Field Duty Papers, obtain Signed Field Duty Papers and bring them to Windcaller Kaldon in Cenarion Hold.\nNote: Healing or casting beneficial spells on a member of the Orgrimmar Legion will flag you for PvP.",
 [8733]="Travel to the continent of Teldrassil and find Malfurion's agent somewhere outside the walls of Darnassus.",
