 [92817]="Maintain your reputation with the Gelkis, and bring a Barbaric Harness to Talra in the Gelkis Village in Desolace.",
 [92818]="Maintain your reputation with the Magram, and bring 2 Massive Iron Axes to Grolkar in the Magram Village in Desolace.",
 [92819]="Use the detonator.",
 [92834]="Collect 10 Al'Aketh Windstone Charms from Al'Aketh cultists found north of Valanaar at the Gustberry Fields or Shrine of Akir.",
 [92840]="Take the Index Esoteria to the Overlook Standing Stones in Shen'dar Highlands and use it on the Windstone Formations in the area to gather data.",
 [92841]="Improve your reputation with the Magram, and locate Orgrul near the Valley of Bones south of Magram Village.",
 [92844]="Maintain your reputation with the Magram, and bring 426 Gently Cursed Bones to Orgrul south of the Magram Village in Desolace.",
 [92846]="Maintain your reputation with the Magram, and slay Outcast Necromancers within the Valley of Bones.",
 [92847]="Maintain your reputation with the Magram, and bring 3 Petrified Bark and 3 Imbued Tears back to Orgrul.",
 [92849]="Keep searching for Fillion Flamebreeze.",
 [92850]="Slay the Shriekling Matriarch in the Shriekling Den then return its head to Fillion Flamebreeze in Valanaar.",
 [92860]="Report to Valennia Stormfist and let her know that the High Order is with them in their fight against the Al'Aketh.",
 [92867]="Defeat the Boulderfist, Syndicate, and Witherbark intruders in Stromgarde Keep and return to Groundskeeper Lomar.",
 [92871]="Report to Valennia Stormfist and let her know that the Windshapers are with them in their fight against the Al'Aketh.",
 [92872]="Throw the Pouch of Tomb Dust into The Great Sea and return to Caretaker Alaric in the Stromgarde Keep crypt.",
 [92873]="Maintain your reputation with the Magram Clan, then bring 426 Well Cursed Bones from a successful ritual back to Orgrul.",
 [92880]="Bring Yorna's Report to Valennia Stormfist in Valanaar.",
 [92881]="Speak with Talaanis Shadowsong in Valanaar.",
 [92893]="Maintain your reputation with the Magram Clan, and slay 5 Gelkis Captives scattered around the Valley of Bones. Return to Orgrul after the task is complete.",
 [92894]="Maintain your reputation with the Magram Clan, and use the Enhanced Necromancy Staff to fully raise undead that are struggling to emerge throughout the Valley of Bones. Return to Orgrul once the Magram army has grown.",
 [92909]="Ozwin Ironsprocket at Saldean's Farm wants you to bring him 14 Golem Isosprings and 5 Harvester Gyrostabilizers.",
 [92910]="Bring the Precessive Autocognition Assembly to Ozwin Ironsprocket at Saldean's Farm.",
 [92911]="Ozwin Ironsprocket at Saldean's Farm wants you to bring him 8 Golem Isosprings, 4 Copper Modulators, and a Crude Scope.",
 [92947]="Slay 7 Al'Aketh Guardians, 7 Al'Aketh Spiritcallers, and 7 Al'Aketh Blademasters, then report to Hyusaa Quickbreeze at the Shrine of Akir.",
 [93034]="Improve your reputation with the Gelkis, and locate Nerlokh near the Valley of Bones far east of Gelkis Village.",
 [93035]="Maintain your reputation with the Gelkis Clan and slay 6 Undead Ravagers, then return to Nerlokh at the southern entrance to Valley of Bones.",
 [93036]="Speak with Sania Silverstream in Shen'dar Village.",
 [93037]="Maintain your reputation with the Gelkis Clan, and bring 1 Necromantic Garb to Nerlokh at the entrance of the Valley of Bones.",
 [93041]="Maintain your reputation with the Gelkis Clan, and bring an Accursed Skull and Gelkis Necromantic Garb to Uthek the Wise in Gelkis Village.",
 [93044]="Maintain your reputation with the Gelkis, and bring Tears of Theradras back to Uthek the Wise in Gelkis Village.",
 [93058]="Maintain your reputation with the Gelkis clan, and rescue 5 Gelkis Captives within the Valley of Bones. Return to Nerlokh near the entrance when you are done.",
 [93062]="Maintain your reputation with the Gelkis Clan, and dispel the curses from 8 failed summons throughout the Valley of Bones.",
 [93065]="Speak with Valennia Stormfist in the Gustberry Lowlands.",
 [93066]="Maintain your reputation with the Magram, and slay quilboar at Bristleback Retreat. Then report to Hagiak at the Magram Front on the other side of Valley of Bones in Desolace.",
 [93072]="Maintain your reputation with the Magram clan and slay 2 Outcast Scouts, 6 Outcast Marauders, and 8 Outcast Necromancers then return to Hagiak at the Magram Front.",
 [93089]="Speak with Elaadrin Evengale when you are prepared to leave Zephras Isle.",
 [93090]="Speak with Ayessa Dawnsinger when you are prepared to leave Zephras Isle.",
 [93122]="Maintain your reputation with the Gelkis, and investigate centaur points of interest within Shen'dralas. Then return to Nerlokh at the entrance of Valley of Bones with your findings.",
 [93125]="Maintain your reputation with the Gelkis, and escort Rokren out of the Outcast Hideaway. Then inform Nerlokh near the Valley of Bones about what happened.",
 [93128]="Maintain your reputation with the Gelkis, and slay Khan Jhen at Magram Village. Once you have succeeded, report to Uthek the Wise in Gelkis Village in Desolace.",
 [93129]="Maintain your reputation with the Magram, and bring 6 Stolen Supplies back to Hagiak at the Magram Front.",
 [93159]="Speak with the Strange Hermit in the Shadowgale Forest and learn more about him.",
 [93160]="Gather 8 Shadowgale Acorns in Shadowgale Forest.",
 [93165]="Collect 5 Al'Aketh Cultist's Ears from the Al'Aketh cultists in Shadowgale Forest, the Shrine of Akir, or Gustberry Lowlands.",
 [93172]="Destroy 10 Wind Hollows in Shadowgale Forest.",
 [93176]="Use the items contained in the Entomology Starter Kit to find and catch an Arbor Tarantula, Hay Weevil Specimen, and a Flesh Picker.",
 [93188]="Maintain your reputation with the Magram, and report back to Orgrul near the northern entrance to Valley of Bones.",
 [93196]="Maintain your reputation with the Magram and perform a necromancy ritual to resurrect Khan Jehn. The ritual site can be found in a tent at the central lake of Magram Village.",
 [93224]="Acquire 5 Carved Centaur Totems by slaying centaur of any clan throughout Desolace, then return them to Captain Pentigast at Nijel's Point.",
 [93225]="Acquire 5 Carved Centaur Totems by slaying centaur of any clan throughout Desolace, then return them to Gurda Wildmane at Ghost Walker Post.",
 [93226]="Bring the Totem Tote to the Magram Quartermaster at Magram Village in the Desolace to significantly increase your reputation with that clan. You must be of at least Neutral standing with the Magram Clan Centaur.",
 [93227]="Bring the Totem Tote to the Gelkis Quartermaster at Gelkis Village in the Desolace to significantly increase your reputation with that clan. You must be of at least Neutral standing with the Gelkis Clan Centaur.",
