 [93318]="Kill Vulgara the Insatiable in the Shen'dar Highlands and bring her head to Danarii Bellowveil.",
 [93319]="Collect 10 Pilfered Windstones from the Highlands Bandits in the Shen'dar Highlands.",
 [93320]="Report to Yorana Windyreed at the eastern watchtower in the Gustberry Lowlands.",
 [93429]="Slay 10 Lost Ones in the Fallow Sanctuary.",
 [93430]="Find the Lost One Fisherman who stole Pelluk's lure, and take it back.",
